SINA_SMART["physio1-endocrine-intro"] = {"lecture":"physio1-endocrine-intro","title":"Introduction to endocrine physiology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-endocrine-intro:e0","text":"Endocrine = ductless, via blood; paracrine, autocrine, intracrine also exist.","topic":"What the endocrine system is","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e1","text":"Peptides: stored, Ca²⁺-dependent exocytosis, membrane receptors, short half-life.","topic":"Hormone classes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e2","text":"Steroids: from cholesterol, made on demand, intracellular receptors.","topic":"Hormone classes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e3","text":"Thyroid hormone: tyrosine-derived but nuclear receptor (exception).","topic":"Hormone classes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e4","text":"Only free hormone is active; binding protein changes alter totals, not free.","topic":"Transport and clearance","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e5","text":"Gs ↑ cAMP (ACTH, TSH, LH, FSH); Gq IP₃/Ca²⁺ (TRH, GnRH); Gi ↓ cAMP (dopamine).","topic":"Receptors and signalling","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e6","text":"RTK: insulin, IGF-1. JAK/STAT: GH, prolactin.","topic":"Receptors and signalling","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e7","text":"Negative feedback is the rule; positive feedback: LH surge, oxytocin in labour.","topic":"Control of secretion","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e8","text":"Tropic ↑ + target ↓ = primary failure; both ↓ = secondary.","topic":"Measuring hormones","sec":5,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-endocrine-intro:e9","text":"Stimulation tests for deficiency; suppression tests for excess.","topic":"Measuring hormones","sec":5,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1dvfqpy":"a","1l0iirn":"a","ghhpro":"a","1i5zv8i":"a","icpzjo":"a","1tix3tn":"a","7kxq5":"a","aiba8t":"a","ox17vj":"a","jp3ad7":"a","svnei5":"a","19uoa7b":"a","11zov4c":"a","a2agpg":"a","1qc93si":"x","1hzdx":"x","1lq5sml":"x","18f3esd":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":4},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-endocrine-intro:e0":{"s":0,"u":["Endocrine = ductless, via blood; paracrine, autocrine, intracrine also exist.","Modes of signalling: endocrine (via blood to distant cells), paracrine (neighbouring cells), autocrine (the same cell) and intracrine (acts inside the cell that made it).","Endocrine glands are ductless and secrete hormones into the blood , acting on distant targets that carry the right receptor (exocrine glands use ducts)."],"dp":[]},"physio1-endocrine-intro:e1":{"s":1,"u":["Peptides: stored, Ca²⁺-dependent exocytosis, membrane receptors, short half-life.","Peptides and proteins (3-200 amino acids; the largest class): made as pre-prohormone → prohormone → hormone in ER and Golgi, stored in granules , released by Ca²⁺-dependent exocytosis , short half-life (minutes).","Amino acid-derived (tyrosine): catecholamines (membrane receptors, very short half-life, 2-3 min) and thyroid hormones (nuclear receptors, half-life of days): the key exception."],"dp":[]},"physio1-endocrine-intro:e2":{"s":1,"u":["Steroids: from cholesterol, made on demand, intracellular receptors.","Steroids : from cholesterol (adrenal cortex, gonads, placenta; vitamin D is related), lipid-soluble, synthesised on demand , carried by proteins, act on intracellular receptors."],"dp":[]},"physio1-endocrine-intro:e3":{"s":1,"u":["Thyroid hormone: tyrosine-derived but nuclear receptor (exception).","Amino acid-derived (tyrosine): catecholamines (membrane receptors, very short half-life, 2-3 min) and thyroid hormones (nuclear receptors, half-life of days): the key exception."],"dp":[{"h":"The tired student (lecture case)","t":"A 20-year-old woman has fatigue, cold intolerance, weight gain, irregular periods, bradycardia and dry skin. TSH is high and free T4 low. The pattern is primary hypothyroidism : the thyroid fails, so low T4 removes negative feedback and the pituitary raises TSH. The lecture's answers: T4 is an amino acid-derived hormone, its receptor is nuclear , it increases metabolic activity and promotes growth and development , and TSH comes from the anterior pituitary . Irregular periods fit too: high TRH also raises prolactin, which suppresses GnRH."}]},"physio1-endocrine-intro:e4":{"s":2,"u":["Only free hormone is active; binding protein changes alter totals, not free.","Trap : when binding proteins rise (pregnancy, oestrogen), total hormone rises but free hormone stays normal.","Hormones circulate free (active) or bound (inactive reservoir)."],"dp":[]},"physio1-endocrine-intro:e5":{"s":3,"u":["Gs ↑ cAMP (ACTH, TSH, LH, FSH); Gq IP₃/Ca²⁺ (TRH, GnRH); Gi ↓ cAMP (dopamine).","GPCRs : Gs → ↑ cAMP → PKA (ACTH, TSH, LH, FSH); Gi → ↓ cAMP (dopamine on lactotrophs); Gq → PLC → IP₃ + DAG → Ca²⁺ and PKC (GnRH, TRH)."],"dp":[]},"physio1-endocrine-intro:e6":{"s":3,"u":["RTK: insulin, IGF-1. JAK/STAT: GH, prolactin.","Class I cytokine receptors have no kinase and use JAK2/STAT (GH, prolactin).","Receptor tyrosine kinases have intrinsic kinase activity (insulin, IGF-1)."],"dp":[]},"physio1-endocrine-intro:e7":{"s":4,"u":["Negative feedback is the rule; positive feedback: LH surge, oxytocin in labour.","Positive feedback is rare, temporary and needs an off switch: oestradiol → LH surge → ovulation; oxytocin in labour.","Negative feedback is the rule: long loop (target hormone → hypothalamus and pituitary), short loop (pituitary → hypothalamus), ultra-short loop (hypothalamic hormone → itself)."],"dp":[]},"physio1-endocrine-intro:e8":{"s":5,"u":["Tropic ↑ + target ↓ = primary failure; both ↓ = secondary.","Tropic ↑ + target ↓ = primary gland failure; tropic ↓ + target ↓ = secondary deficiency; tropic ↓ + target ↑ = autonomous target gland; tropic ↑ + target ↑ = autonomous tropic secretion or feedback failure; hormone ↑ with substrate ↑ = resistance ."],"dp":[]},"physio1-endocrine-intro:e9":{"s":5,"u":["Stimulation tests for deficiency; suppression tests for excess.","Dynamic tests: stimulation tests for deficiency (ACTH stimulation, OGTT) and suppression tests for excess (dexamethasone suppression, glucose suppression of GH)."],"dp":[]}},"meta":{"1dvfqpy":{"a":"recall","vg":"physio1-endocrine-intro:e3/recall/1"},"1l0iirn":{"a":"recall","vg":"physio1-endocrine-intro:e2/recall/1"},"ghhpro":{"a":"recall","vg":"physio1-endocrine-intro:e1/recall/1"},"1i5zv8i":{"a":"recall","vg":"physio1-endocrine-intro:e6/recall/1"},"icpzjo":{"a":"recall","vg":"physio1-endocrine-intro:e6/recall/1"},"1tix3tn":{"a":"recall","vg":"physio1-endocrine-intro:e5/recall/1"},"7kxq5":{"a":"recall","vg":"physio1-endocrine-intro:e5/recall/2"},"aiba8t":{"a":"relationship","vg":"physio1-endocrine-intro:e4/relationship/1"},"ox17vj":{"a":"recall","vg":"physio1-endocrine-intro:e4/recall/1"},"jp3ad7":{"a":"recall","vg":"physio1-endocrine-intro:e7/recall/1"},"svnei5":{"a":"recall","vg":"physio1-endocrine-intro:e9/recall/1"},"19uoa7b":{"a":"recall","vg":"physio1-endocrine-intro:e0/recall/1"},"11zov4c":{"a":"recall","vg":"physio1-endocrine-intro:e3/recall/2"},"a2agpg":{"a":"recall","vg":"physio1-endocrine-intro:e8/recall/1"}},"explRev":"76c9631caeab"};
